#include <stdbool.h>
#include <string.h>

#define MAX 30

typedef struct {
    int r, c;
} Point;

int m, n;
int directions[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};

bool inGrid(int r, int c) {
    return r >= 0 && r < m && c >= 0 && c < n;
}

// DFS to count connected land cells and mark visited
void dfs(int r, int c, int grid[MAX][MAX], bool visited[MAX][MAX]) {
    visited[r][c] = true;
    for (int d = 0; d < 4; d++) {
        int nr = r + directions[d][0];
        int nc = c + directions[d][1];
        if (inGrid(nr, nc) && !visited[nr][nc] && grid[nr][nc] == 1) {
            dfs(nr, nc, grid, visited);
        }
    }
}

// Count number of islands in grid
int countIslands(int grid[MAX][MAX]) {
    bool visited[MAX][MAX];
    memset(visited, 0, sizeof(visited));
    int islands = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 1 && !visited[i][j]) {
                islands++;
                dfs(i, j, grid, visited);
            }
        }
    }
    return islands;
}

// Check if grid is connected (exactly one island)
bool isConnected(int grid[MAX][MAX]) {
    int islands = countIslands(grid);
    return islands == 1;
}

// Check if the grid is disconnected (0 or >1 islands)
bool isDisconnected(int grid[MAX][MAX]) {
    int islands = countIslands(grid);
    return islands != 1;
}

int minDays(int** grid, int gridSize, int* gridColSize){
    m = gridSize;
    n = gridColSize[0];
    int g[MAX][MAX];
    int landCount = 0;

    // Copy grid to local array and count land cells
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            g[i][j] = grid[i][j];
            if (g[i][j] == 1) landCount++;
        }
    }

    // If already disconnected (0 or >1 islands), return 0
    if (isDisconnected(g)) return 0;

    // If only one land cell, flipping it disconnects (0 islands)
    if (landCount == 1) return 1;

    // Try flipping each land cell to water and check connectivity
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (g[i][j] == 1) {
                g[i][j] = 0;
                if (isDisconnected(g)) {
                    g[i][j] = 1;
                    return 1;
                }
                g[i][j] = 1;
            }
        }
    }

    // If no single flip disconnects, answer is 2
    return 2;
}

